import{_ as p,r as s,o,c as i,e as a,a as c,s as l}from"./chunks/framework.CXcwiNg-.js";const m=JSON.parse('{"title":"Request & Input - October CMS - 3.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"Basic Input","slug":"basic-input","link":"#basic-input","children":[{"level":4,"title":"Retrieving an Input Value","slug":"retrieving-an-input-value","link":"#retrieving-an-input-value","children":[]},{"level":4,"title":"Retrieving a Default Value if the Input Value is Absent","slug":"retrieving-a-default-value-if-the-input-value-is-absent","link":"#retrieving-a-default-value-if-the-input-value-is-absent","children":[]},{"level":4,"title":"Determining if an Input Value is Present","slug":"determining-if-an-input-value-is-present","link":"#determining-if-an-input-value-is-present","children":[]},{"level":4,"title":"Getting All Input for the Request","slug":"getting-all-input-for-the-request","link":"#getting-all-input-for-the-request","children":[]},{"level":4,"title":"Getting Only Some of the Request Input","slug":"getting-only-some-of-the-request-input","link":"#getting-only-some-of-the-request-input","children":[]}]},{"level":2,"title":"Cookies","slug":"cookies","link":"#cookies","children":[{"level":4,"title":"Retrieving a Cookie Value","slug":"retrieving-a-cookie-value","link":"#retrieving-a-cookie-value","children":[]},{"level":4,"title":"Attaching a New Cookie to a Response","slug":"attaching-a-new-cookie-to-a-response","link":"#attaching-a-new-cookie-to-a-response","children":[]},{"level":4,"title":"Queueing a Cookie for the Next Response","slug":"queueing-a-cookie-for-the-next-response","link":"#queueing-a-cookie-for-the-next-response","children":[]},{"level":4,"title":"Creating a Cookie That Lasts Forever","slug":"creating-a-cookie-that-lasts-forever","link":"#creating-a-cookie-that-lasts-forever","children":[]},{"level":4,"title":"Handling Cookies Without Encryption","slug":"handling-cookies-without-encryption","link":"#handling-cookies-without-encryption","children":[]}]},{"level":2,"title":"Old Input","slug":"old-input","link":"#old-input","children":[{"level":4,"title":"Flashing Input to the Session","slug":"flashing-input-to-the-session","link":"#flashing-input-to-the-session","children":[]},{"level":4,"title":"Flashing Only Some Input to the Session","slug":"flashing-only-some-input-to-the-session","link":"#flashing-only-some-input-to-the-session","children":[]},{"level":4,"title":"Retrieving Old Data","slug":"retrieving-old-data","link":"#retrieving-old-data","children":[]}]},{"level":2,"title":"Files","slug":"files","link":"#files","children":[]},{"level":2,"title":"Request Information","slug":"request-information","link":"#request-information","children":[{"level":4,"title":"Retrieving the Request URI","slug":"retrieving-the-request-uri","link":"#retrieving-the-request-uri","children":[]},{"level":4,"title":"Retrieving the Request Method","slug":"retrieving-the-request-method","link":"#retrieving-the-request-method","children":[]},{"level":4,"title":"Determining if the Request Path Matches a Pattern","slug":"determining-if-the-request-path-matches-a-pattern","link":"#determining-if-the-request-path-matches-a-pattern","children":[]},{"level":4,"title":"Get the Request URL","slug":"get-the-request-url","link":"#get-the-request-url","children":[]},{"level":4,"title":"Retrieve a Request URI Segment","slug":"retrieve-a-request-uri-segment","link":"#retrieve-a-request-uri-segment","children":[]},{"level":4,"title":"Retrieving a Request Header","slug":"retrieving-a-request-header","link":"#retrieving-a-request-header","children":[]},{"level":4,"title":"Retrieving Values from $_SERVER","slug":"retrieving-values-from-server","link":"#retrieving-values-from-server","children":[]},{"level":4,"title":"Determining if the Request is Over HTTPS","slug":"determining-if-the-request-is-over-https","link":"#determining-if-the-request-is-over-https","children":[]},{"level":4,"title":"Determine if the Request is Using AJAX","slug":"determine-if-the-request-is-using-ajax","link":"#determine-if-the-request-is-using-ajax","children":[]},{"level":4,"title":"Determine if the Request has JSON Content Type","slug":"determine-if-the-request-has-json-content-type","link":"#determine-if-the-request-has-json-content-type","children":[]},{"level":4,"title":"Determine if the Request is Asking for JSON","slug":"determine-if-the-request-is-asking-for-json","link":"#determine-if-the-request-is-asking-for-json","children":[]},{"level":4,"title":"Checking the Requested Response Format","slug":"checking-the-requested-response-format","link":"#checking-the-requested-response-format","children":[]}]}],"relativePath":"3.x/extend/services/request-input.md","filePath":"3.x/extend/services/request-input.md"}'),r={name:"3.x/extend/services/request-input.md"};function u(k,n,d,h,g,f){const e=s("pre-heading"),t=s("post-heading");return o(),i("div",null,[a(e),n[0]||(n[0]=c("h1",null,"Request & Input",-1)),a(t),n[1]||(n[1]=l(`<h2 id="basic-input"><a href="#basic-input" class="header-anchor">#</a> Basic Input</h2><p>You may access all user input with a few simple methods. You do not need to worry about the HTTP verb for the request when using the <code>Input</code> facade, as input is accessed in the same way for all verbs. The global <code>input</code> <a href="./helpers.html">helper function</a> is an alias for <code>Input::get</code>.</p><h4 id="retrieving-an-input-value"><a href="#retrieving-an-input-value" class="header-anchor">#</a> Retrieving an Input Value</h4><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$name</span> <span class="token operator">=</span> <span class="token class-name static-context">Input</span><span class="token operator">::</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$name</span> <span class="token operator">=</span> <span class="token function">input</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="retrieving-a-default-value-if-the-input-value-is-absent"><a href="#retrieving-a-default-value-if-the-input-value-is-absent" class="header-anchor">#</a> Retrieving a Default Value if the Input Value is Absent</h4><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$name</span> <span class="token operator">=</span> <span class="token class-name static-context">Input</span><span class="token operator">::</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;Sally&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="determining-if-an-input-value-is-present"><a href="#determining-if-an-input-value-is-present" class="header-anchor">#</a> Determining if an Input Value is Present</h4><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token class-name static-context">Input</span><span class="token operator">::</span><span class="token function">has</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">//</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="getting-all-input-for-the-request"><a href="#getting-all-input-for-the-request" class="header-anchor">#</a> Getting All Input for the Request</h4><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$input</span> <span class="token operator">=</span> <span class="token class-name static-context">Input</span><span class="token operator">::</span><span class="token function">all</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="getting-only-some-of-the-request-input"><a href="#getting-only-some-of-the-request-input" class="header-anchor">#</a> Getting Only Some of the Request Input</h4><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$input</span> <span class="token operator">=</span> <span class="token class-name static-context">Input</span><span class="token operator">::</span><span class="token function">only</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;username&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;password&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$input</span> <span class="token operator">=</span> <span class="token class-name static-context">Input</span><span class="token operator">::</span><span class="token function">except</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;credit_card&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>When working on forms with &quot;array&quot; inputs, you may use dot notation to access the arrays:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$input</span> <span class="token operator">=</span> <span class="token class-name static-context">Input</span><span class="token operator">::</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;products.0.name&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><div class="custom-block tip"><p>Some JavaScript libraries such as Backbone may send input to the application as JSON. You may access this data via <code>Input::get</code> like normal.</p></div><h2 id="cookies"><a href="#cookies" class="header-anchor">#</a> Cookies</h2><p>By default, all cookies created by the October CMS are encrypted and signed with an authentication code, meaning they will be considered invalid if they have been changed by the client. Cookies named in the <code>system.unencrypt_cookies</code> config key will not be encrypted.</p><h4 id="retrieving-a-cookie-value"><a href="#retrieving-a-cookie-value" class="header-anchor">#</a> Retrieving a Cookie Value</h4><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$value</span> <span class="token operator">=</span> <span class="token class-name static-context">Cookie</span><span class="token operator">::</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="attaching-a-new-cookie-to-a-response"><a href="#attaching-a-new-cookie-to-a-response" class="header-anchor">#</a> Attaching a New Cookie to a Response</h4><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$response</span> <span class="token operator">=</span> <span class="token class-name static-context">Response</span><span class="token operator">::</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Hello World&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$response</span><span class="token operator">-&gt;</span><span class="token function">withCookie</span><span class="token punctuation">(</span><span class="token class-name static-context">Cookie</span><span class="token operator">::</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;value&#39;</span><span class="token punctuation">,</span> <span class="token variable">$minutes</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="queueing-a-cookie-for-the-next-response"><a href="#queueing-a-cookie-for-the-next-response" class="header-anchor">#</a> Queueing a Cookie for the Next Response</h4><p>If you would like to set a cookie before a response has been created, use the <code>Cookie::queue</code> method. The cookie will automatically be attached to the final response from your application.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Cookie</span><span class="token operator">::</span><span class="token function">queue</span><span class="token punctuation">(</span><span class="token variable">$name</span><span class="token punctuation">,</span> <span class="token variable">$value</span><span class="token punctuation">,</span> <span class="token variable">$minutes</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="creating-a-cookie-that-lasts-forever"><a href="#creating-a-cookie-that-lasts-forever" class="header-anchor">#</a> Creating a Cookie That Lasts Forever</h4><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$cookie</span> <span class="token operator">=</span> <span class="token class-name static-context">Cookie</span><span class="token operator">::</span><span class="token function">forever</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;value&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="handling-cookies-without-encryption"><a href="#handling-cookies-without-encryption" class="header-anchor">#</a> Handling Cookies Without Encryption</h4><p>If you don&#39;t want some cookies to be encrypted or decrypted, you can specify them in configuration. This is useful, for example, when you want to pass data from frontend to server side backend via cookies, and vice versa.</p><p>Add names of the cookies that should not be encrypted or decrypted to <code>unencrypt_cookies</code> parameter in the <code>config/system.php</code> configuration file.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token string single-quoted-string">&#39;unencrypt_cookies&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;my_cookie&#39;</span><span class="token punctuation">,</span>
<span class="token punctuation">]</span><span class="token punctuation">,</span>
</code></pre></div><p>Alternatively for plugins, you can also add these dynamically from <code>Plugin.php</code> of your plugin.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">boot</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token class-name static-context">Config</span><span class="token operator">::</span><span class="token function">push</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;system.unencrypt_cookies&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;my_cookie&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h2 id="old-input"><a href="#old-input" class="header-anchor">#</a> Old Input</h2><p>You may need to keep input from one request until the next request. For example, you may need to re-populate a form after checking it for validation errors.</p><h4 id="flashing-input-to-the-session"><a href="#flashing-input-to-the-session" class="header-anchor">#</a> Flashing Input to the Session</h4><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Input</span><span class="token operator">::</span><span class="token function">flash</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="flashing-only-some-input-to-the-session"><a href="#flashing-only-some-input-to-the-session" class="header-anchor">#</a> Flashing Only Some Input to the Session</h4><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Input</span><span class="token operator">::</span><span class="token function">flashOnly</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;username&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;email&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token class-name static-context">Input</span><span class="token operator">::</span><span class="token function">flashExcept</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;password&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Since you often will want to flash input in association with a redirect to the previous page, you may easily chain input flashing onto a redirect.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token class-name static-context">Redirect</span><span class="token operator">::</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;form&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">withInput</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token keyword">return</span> <span class="token class-name static-context">Redirect</span><span class="token operator">::</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;form&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">withInput</span><span class="token punctuation">(</span><span class="token class-name static-context">Input</span><span class="token operator">::</span><span class="token function">except</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;password&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><div class="custom-block tip"><p>You may flash other data across requests using the <a href="./session.html">Session</a> class.</p></div><h4 id="retrieving-old-data"><a href="#retrieving-old-data" class="header-anchor">#</a> Retrieving Old Data</h4><p>Fetch individual input value.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Input</span><span class="token operator">::</span><span class="token function">old</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;username&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Fetch all old input values.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$data</span> <span class="token operator">=</span> <span class="token class-name static-context">Input</span><span class="token operator">::</span><span class="token function">old</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="files"><a href="#files" class="header-anchor">#</a> Files</h2><p>You can retrieve uploaded files from the request using the <code>file</code> method on the <code>Input</code> facade or the global <code>files()</code> helper.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$file</span> <span class="token operator">=</span> <span class="token class-name static-context">Input</span><span class="token operator">::</span><span class="token function">file</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;photo&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$file</span> <span class="token operator">=</span> <span class="token function">files</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;photo&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>To determine if a file is present on the request, use the <code>hasFile</code> method.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token class-name static-context">Input</span><span class="token operator">::</span><span class="token function">hasFile</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;photo&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">//</span>
<span class="token punctuation">}</span>
</code></pre></div><p>In addition to checking if the file is present, you may verify that there were no problems uploading the file via the isValid method.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$file</span><span class="token operator">-&gt;</span><span class="token function">isValid</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">//</span>
<span class="token punctuation">}</span>
</code></pre></div><p>The returned file object has a variety of methods related to the uploaded file.</p><div class="table"><table tabindex="0"><thead><tr><th>Method Name</th><th>Purpose</th></tr></thead><tbody><tr><td><strong>move($destinationPath, $fileName)</strong></td><td>Moves the uploaded file to a local path</td></tr><tr><td><strong>store($folder, $disk)</strong></td><td>Stores the file using the <a href="./../../extend/services/storage.html">storage service</a>.</td></tr><tr><td><strong>storeAs($folder, $name, $disk)</strong></td><td>Stores the file with a specific name using the <a href="./../../extend/services/storage.html">storage service</a>.</td></tr><tr><td><strong>extension()</strong></td><td>Guesses the extension based on the file contents</td></tr><tr><td><strong>getRealPath()</strong></td><td>Returns the local path</td></tr><tr><td><strong>getClientOriginalName()</strong></td><td>Returns the original name</td></tr><tr><td><strong>getClientOriginalExtension()</strong></td><td>Returns the original extension</td></tr><tr><td><strong>getSize()</strong></td><td>Returns the size</td></tr><tr><td><strong>getMimeType()</strong></td><td>Returns the MIME type</td></tr></tbody></table></div><p>An example of moving an uploaded file.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$file</span><span class="token operator">-&gt;</span><span class="token function">move</span><span class="token punctuation">(</span><span class="token variable">$destinationPath</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$file</span><span class="token operator">-&gt;</span><span class="token function">move</span><span class="token punctuation">(</span><span class="token variable">$destinationPath</span><span class="token punctuation">,</span> <span class="token variable">$fileName</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Examples of <a href="./storage.html">storing an uploaded file</a> in a folder (first argument) and an optional disk (second argument).</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$file</span><span class="token operator">-&gt;</span><span class="token function">store</span><span class="token punctuation">(</span><span class="token variable">$folder</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$file</span><span class="token operator">-&gt;</span><span class="token function">store</span><span class="token punctuation">(</span><span class="token variable">$folder</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;s3&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><div class="custom-block warning"><p>The folder names <code>media</code>, <code>resources</code>, <code>uploads</code> or <code>public</code> are reserved.</p></div><p>Examples of <code>storeAs</code> storing the file with a custom disk name (second argument). The <code>storePubliclyAs</code> stores the file with public visibility.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$file</span><span class="token operator">-&gt;</span><span class="token function">storeAs</span><span class="token punctuation">(</span><span class="token variable">$folder</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;avatar&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$file</span><span class="token operator">-&gt;</span><span class="token function">storeAs</span><span class="token punctuation">(</span><span class="token variable">$folder</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;avatar&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;s3&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$file</span><span class="token operator">-&gt;</span><span class="token function">storePublicly</span><span class="token punctuation">(</span><span class="token variable">$folder</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;s3&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$file</span><span class="token operator">-&gt;</span><span class="token function">storePubliclyAs</span><span class="token punctuation">(</span><span class="token variable">$folder</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;avatar&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;s3&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>An example of retrieving the path to an uploaded file.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$path</span> <span class="token operator">=</span> <span class="token variable">$file</span><span class="token operator">-&gt;</span><span class="token function">getRealPath</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>An example of retrieving the original name of an uploaded file.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$name</span> <span class="token operator">=</span> <span class="token variable">$file</span><span class="token operator">-&gt;</span><span class="token function">getClientOriginalName</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Retrieving the extension of an uploaded file.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$extension</span> <span class="token operator">=</span> <span class="token variable">$file</span><span class="token operator">-&gt;</span><span class="token function">getClientOriginalExtension</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Retrieving the size of an uploaded file.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$size</span> <span class="token operator">=</span> <span class="token variable">$file</span><span class="token operator">-&gt;</span><span class="token function">getSize</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Retrieving the MIME type of an uploaded file.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$mime</span> <span class="token operator">=</span> <span class="token variable">$file</span><span class="token operator">-&gt;</span><span class="token function">getMimeType</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="request-information"><a href="#request-information" class="header-anchor">#</a> Request Information</h2><p>The <code>Request</code> class provides many methods for examining the HTTP request for your application and extends the <code>Symfony\\Component\\HttpFoundation\\Request</code> class. Here are some of the highlights.</p><h4 id="retrieving-the-request-uri"><a href="#retrieving-the-request-uri" class="header-anchor">#</a> Retrieving the Request URI</h4><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$uri</span> <span class="token operator">=</span> <span class="token class-name static-context">Request</span><span class="token operator">::</span><span class="token function">path</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="retrieving-the-request-method"><a href="#retrieving-the-request-method" class="header-anchor">#</a> Retrieving the Request Method</h4><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$method</span> <span class="token operator">=</span> <span class="token class-name static-context">Request</span><span class="token operator">::</span><span class="token function">method</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token class-name static-context">Request</span><span class="token operator">::</span><span class="token function">isMethod</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;post&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">//</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="determining-if-the-request-path-matches-a-pattern"><a href="#determining-if-the-request-path-matches-a-pattern" class="header-anchor">#</a> Determining if the Request Path Matches a Pattern</h4><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token class-name static-context">Request</span><span class="token operator">::</span><span class="token function">is</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;admin/*&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">//</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="get-the-request-url"><a href="#get-the-request-url" class="header-anchor">#</a> Get the Request URL</h4><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$url</span> <span class="token operator">=</span> <span class="token class-name static-context">Request</span><span class="token operator">::</span><span class="token function">url</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="retrieve-a-request-uri-segment"><a href="#retrieve-a-request-uri-segment" class="header-anchor">#</a> Retrieve a Request URI Segment</h4><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$segment</span> <span class="token operator">=</span> <span class="token class-name static-context">Request</span><span class="token operator">::</span><span class="token function">segment</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="retrieving-a-request-header"><a href="#retrieving-a-request-header" class="header-anchor">#</a> Retrieving a Request Header</h4><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$value</span> <span class="token operator">=</span> <span class="token class-name static-context">Request</span><span class="token operator">::</span><span class="token function">header</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Content-Type&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="retrieving-values-from-server"><a href="#retrieving-values-from-server" class="header-anchor">#</a> Retrieving Values from $_SERVER</h4><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$value</span> <span class="token operator">=</span> <span class="token class-name static-context">Request</span><span class="token operator">::</span><span class="token function">server</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;PATH_INFO&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="determining-if-the-request-is-over-https"><a href="#determining-if-the-request-is-over-https" class="header-anchor">#</a> Determining if the Request is Over HTTPS</h4><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token class-name static-context">Request</span><span class="token operator">::</span><span class="token function">secure</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">//</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="determine-if-the-request-is-using-ajax"><a href="#determine-if-the-request-is-using-ajax" class="header-anchor">#</a> Determine if the Request is Using AJAX</h4><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token class-name static-context">Request</span><span class="token operator">::</span><span class="token function">ajax</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">//</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="determine-if-the-request-has-json-content-type"><a href="#determine-if-the-request-has-json-content-type" class="header-anchor">#</a> Determine if the Request has JSON Content Type</h4><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token class-name static-context">Request</span><span class="token operator">::</span><span class="token function">isJson</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">//</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="determine-if-the-request-is-asking-for-json"><a href="#determine-if-the-request-is-asking-for-json" class="header-anchor">#</a> Determine if the Request is Asking for JSON</h4><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token class-name static-context">Request</span><span class="token operator">::</span><span class="token function">wantsJson</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">//</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="checking-the-requested-response-format"><a href="#checking-the-requested-response-format" class="header-anchor">#</a> Checking the Requested Response Format</h4><p>The <code>Request::format</code> method will return the requested response format based on the HTTP Accept header:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token class-name static-context">Request</span><span class="token operator">::</span><span class="token function">format</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">==</span> <span class="token string single-quoted-string">&#39;json&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">//</span>
<span class="token punctuation">}</span>
</code></pre></div>`,99))])}const q=p(r,[["render",u]]);export{m as __pageData,q as default};
